pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, uint256 d, uint256 a) public {
        vm.assume(actor != address(c) && actor != address(this));
        vm.assume(actor.code.length == 0);
        vm.assume(d > 0 && d < 2**128);
        a = bound(a, 0, d);
        vm.deal(actor, d);
        vm.prank(actor);
        c.deposit{value: d}();
        vm.prank(actor);
        c.withdraw(a);
        // Conservation: contract ether balance equals sum of recorded balances
        assertTrue(address(c).balance == c.balances(actor));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, type(uint128).max);
        Actor actor = new Actor(c);
        vm.deal(address(actor), amount);

        actor.setAccept(true);
        actor.doDeposit(amount);

        actor.setAccept(true);
        actor.doWithdraw(amount);

        // In P the recorded balance is now 0, so refund() transfers 0 wei and
        // succeeds even though the caller rejects Ether; in M the stale balance
        // is positive, so refund() tries to send `amount` wei and reverts.
        actor.setAccept(false);
        bool ok = true;
        try actor.doRefund() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

contract Actor {
    C c;
    bool public accept;

    constructor(C c_) {
        c = c_;
        accept = true;
    }

    function setAccept(bool b) external {
        accept = b;
    }

    function doDeposit(uint256 d) external {
        c.deposit{value: d}();
    }

    function doWithdraw(uint256 a) external {
        c.withdraw(a);
    }

    function doRefund() external {
        c.refund();
    }

    receive() external payable {
        require(accept, "refusing ether");
    }
}

