pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1e18);
        Attacker atk = new Attacker(c);
        vm.deal(address(atk), amount);
        atk.attack(amount);
        // Universal rule: a user can never withdraw more ether than they deposited.
        assertTrue(atk.received() <= amount);
    }
}

contract Attacker {
    C c;
    uint256 public received;
    uint256 amt;
    bool withdrawing;

    constructor(C _c) { c = _c; }

    function attack(uint256 a) external {
        amt = a;
        c.deposit{value: a}();
        withdrawing = true;
        c.withdraw(a);
        withdrawing = false;
    }

    receive() external payable {
        received += msg.value;
        if (withdrawing && address(c).balance >= amt) {
            c.withdraw(amt);
        }
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function test(uint256 a, uint256 b) public {
        require(a > 0 && b > 0 && a != b);
        require(address(this).balance >= a + b);

        c.deposit{value: a}();
        c.deposit{value: b}();

        bool reverted = false;
        // state-changing call must be top-level; use try pattern via wrapper not allowed,
        // so perform withdraw of a+b directly; on P it succeeds, on M it reverts.
        c.withdraw(a + b);

        assert(address(this).balance == 0 ether - 0 ether + address(this).balance || !reverted);
        assert(address(c).balance == 0);
    }

    receive() external payable {}
    fallback() external payable {}
}

