contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 a, uint256 b) public payable {
        require(a > 0 && b > 0);
        require(address(this).balance >= a + b);
        bool reverted1; try c.deposit{value: a}() { reverted1 = false; } catch { reverted1 = true; }
        bool reverted2; try c.deposit{value: b}() { reverted2 = false; } catch { reverted2 = true; }
        bool reverted3; try c.withdraw(a + b) { reverted3 = false; } catch { reverted3 = true; }
        assert(reverted1 == false && reverted2 == false && reverted3 == false);
    }
